// Bitfield Description : The number of counter banks supported by the IOMMU. Each bank contains two or more counter and control registers as specified by NCounter. For each counter bank, a corresponding control bit is in IOMMU Counter PASID Bank-Lock Register IOMMUMMIO::IOMMU_MMIO_COUNTER_PASID_BANK_LOCK_0, IOMMU Counter Domain Bank-Lock Register IOMMUMMIO::IOMMU_MMIO_COUNTER_DOMAIN_BANK_LOCK_0 and IOMMU Counter DeviceID Bank-Lock Register [MMIO Offset 4018h]. Each supported event counter bank is in a distinct, consecutive 4K byte page. The limit of 63 counter banks is architectural and an implementation may set a lower value.
// 0=No event counter banks supported.
// 1-63=The number of event counter banks supported.
// Note: IOMMU event counter banks are numbered starting with 0.
