/***********************************************************
* Register Name : IOMMU_MMIO_STATUS_0
* Register Description :
* 
* Visibility : 0x2
************************************************************/

// Bitfield Description : 1=IOMMU event log overflow has occurred.
// This bit is set when a new event is to be written to the event log and there is no usable entry in the event log, causing the new event information to be discarded. An interrupt is generated when EventOverflow=1b and IOMMUMMIO::IOMMU_MMIO_CNTRL_0[EVENT_INT_EN]=1b. No new event log entries are written while this bit is set.
#define IOMMU_MMIO_STATUS_0_EVENT_OVERFLOW_OFFSET      0
#define IOMMU_MMIO_STATUS_0_EVENT_OVERFLOW_MASK        0x1

// Bitfield Description : 1=Event entry written to the event log by the IOMMU.
// 0=No event entry written to the event log by the IOMMU.
// An interrupt is generated when EventLogInt=1b and IOMMUMMIO::IOMMU_MMIO_CNTRL_0[EVENT_INT_EN]=1b.
#define IOMMU_MMIO_STATUS_0_EVENT_LOGINT_OFFSET      1
#define IOMMU_MMIO_STATUS_0_EVENT_LOGINT_MASK        0x2

// Bitfield Description : 1=COMPLETION_WAIT command completed.
// This bit is only set if the i bit is set in the COMPLETION_WAIT command. An interrupt is generated when ComWaitInt=1b and MMIO Offset 0018h[ComWaitIntEn]=1b.
#define IOMMU_MMIO_STATUS_0_COMWAIT_INT_OFFSET      2
#define IOMMU_MMIO_STATUS_0_COMWAIT_INT_MASK        0x4

// Bitfield Description : 1=events are logged as they occur.
// 0=event reports are discarded without logging.
// When EventOverflow=1b, the IOMMU does not write new event log entries even when EventLogRun=1b. When halted, event logging is restarted by using MMIO Offset 0018h[EventLogEn].
#define IOMMU_MMIO_STATUS_0_EVENT_LOGRUN_OFFSET      3
#define IOMMU_MMIO_STATUS_0_EVENT_LOGRUN_MASK        0x8

// Bitfield Description : 1=commands may be fetched from the command buffer.
// 0=IOMMU has stopped fetching new commands.
// The IOMMU freezes command processing after COMMAND_HARDWARE_ERROR or ILLEGAL_COMMAND_ERROR errors. When frozen, command fetching is restarted by using IOMMUMMIO::IOMMU_MMIO_CNTRL_0[CMD_BUF_EN].
#define IOMMU_MMIO_STATUS_0_CMD_BUFRUN_OFFSET      4
#define IOMMU_MMIO_STATUS_0_CMD_BUFRUN_MASK        0x10

// Bitfield Description : 1=IOMMU PPR log overflow has occurred. This bit is set when a new peripheral page service request is to be written to the PPR log and there is no usable entry in the PPR log, causing the new information to be discarded.
// 0=There is no IOMMU PPR log overflow.
// An interrupt is generated when PPR_OVERFLOW=1b and [MMIO Offset 0018h[PPR_INT_EN]]=1b. No new PPR log entries are written while this bit is set.
#define IOMMU_MMIO_STATUS_0_PPR_OVERFLOW_OFFSET      5
#define IOMMU_MMIO_STATUS_0_PPR_OVERFLOW_MASK        0x20

// Bitfield Description : 1=PPR request entry written to the PPR log by the IOMMU.
// 0=No PPR entry written to the PPR log by the IOMMU.
// An interrupt is generated when PPR_INT=1b and IOMMUMMIO::IOMMU_MMIO_CNTRL_0[PPR_INT_EN]=1b.
#define IOMMU_MMIO_STATUS_0_PPR_INT_OFFSET      6
#define IOMMU_MMIO_STATUS_0_PPR_INT_MASK        0x40

// Bitfield Description : 1=PPR requests are logged as they occur.
// 0=PPR requests are discarded without logging.
// When PPR_OVERFLOW=1b, the IOMMU does not write new PPR log entries even when PPR_RUN=1b. When halted, PPR request logging is restarted by using IOMMUMMIO::IOMMU_MMIO_CNTRL_0[PPR_LOG_EN].
#define IOMMU_MMIO_STATUS_0_PPR_RUN_OFFSET      7
#define IOMMU_MMIO_STATUS_0_PPR_RUN_MASK        0x80

// Bitfield Description : 1=GA requests are logged as they occur.
// 0=GA requests are discarded without logging.
// When GA_OVERFLOW=1b, the IOMMU does not write new GA log entries even when GA_RUN=1b. When halted, GA request logging is restarted by using IOMMUMMIO::IOMMU_MMIO_CNTRL_0[GA_LOG_EN].
#define IOMMU_MMIO_STATUS_0_GA_RUN_OFFSET      8
#define IOMMU_MMIO_STATUS_0_GA_RUN_MASK        0x100

// Bitfield Description : 1=IOMMU GA log overflow has occurred. This bit is set when a new peripheral page service request is to be written to the GA log and there is no usable entry in the GA log, causing the new information to be discarded.
// 0=There is no IOMMU GA log overflow.
// An interrupt is generated when GA_OVERFLOW=1b and [MMIO Offset 0018h[GA_INT_EN]]=1b. No new GA log entries are written while this bit is set.
#define IOMMU_MMIO_STATUS_0_GA_OVERFLOW_OFFSET      9
#define IOMMU_MMIO_STATUS_0_GA_OVERFLOW_MASK        0x200

// Bitfield Description : 1=GA request entry written to the GA log by the IOMMU.
// 0=No GA entry written to the GA log by the IOMMU.
// An interrupt is generated when GA_INT=1b and [MMIO Offset 0018h[GA_INT_EN]]=1b.
#define IOMMU_MMIO_STATUS_0_GA_INT_OFFSET      10
#define IOMMU_MMIO_STATUS_0_GA_INT_MASK        0x400

// Bitfield Description : 1=IOMMU PPR log B overflow has occurred. This bit is set when a new peripheral page service request is to be written to the PPR log and there is no usable entry in the PPR log, causing the new information to be discarded.
// 0=There is no IOMMU PPR log overflow.
// An interrupt is generated when PPR_OVERFLOW=1b and [MMIO Offset 0018h[PPR_INT_EN]]=1b. No new PPR log entries are written while this bit is set.
#define IOMMU_MMIO_STATUS_0_PPR_B_OVERFLOW_OFFSET      11
#define IOMMU_MMIO_STATUS_0_PPR_B_OVERFLOW_MASK        0x800

// Bitfield Description : 0=PPR default Buf being used by hardware, 1=PPR Buf B being used by hardware.
#define IOMMU_MMIO_STATUS_0_PPR_BUF_ACTIVE_OFFSET      12
#define IOMMU_MMIO_STATUS_0_PPR_BUF_ACTIVE_MASK        0x1000

// Bitfield Description : 
#define IOMMU_MMIO_STATUS_0_Reserved_14_13_OFFSET      13
#define IOMMU_MMIO_STATUS_0_Reserved_14_13_MASK        0x6000

// Bitfield Description : 1=IOMMU event log B overflow has occurred.
// This bit is set when a new event is to be written to the event log and there is no usable entry in the event log, causing the new event information to be discarded. An interrupt is generated when EventOverflow=1b and IOMMUMMIO::IOMMU_MMIO_CNTRL_0[EVENT_INT_EN]=1b. No new event log entries are written while this bit is set.
#define IOMMU_MMIO_STATUS_0_EVENT_B_OVERFLOW_OFFSET      15
#define IOMMU_MMIO_STATUS_0_EVENT_B_OVERFLOW_MASK        0x8000

// Bitfield Description : 0=EVENT default Buf being used by hardware, 1=EVENT Buf B being used by hardware.
#define IOMMU_MMIO_STATUS_0_EVENT_BUF_ACTIVE_OFFSET      16
#define IOMMU_MMIO_STATUS_0_EVENT_BUF_ACTIVE_MASK        0x10000

// Bitfield Description : 1=IOMMU event log B has reached early overflow threshold. This bit is set when the respected PPR log has reached the programmable threshold and when Overflow_early_en=1. When Auto_resp_en=1, hardware will generates auto responses for the last PPR request and let Stop marker PPR msg through the log.
#define IOMMU_MMIO_STATUS_0_PPR_B_OVERFLOW_EARLY_OFFSET      17
#define IOMMU_MMIO_STATUS_0_PPR_B_OVERFLOW_EARLY_MASK        0x20000

// Bitfield Description : 1=IOMMU event log A has reached early overflow threshold. This bit is set when the respected PPR log has reached the programmable threshold and when Overflow_early_en=1. When Auto_resp_en=1, hardware generates auto responses for the last PPR request and let Stop marker PPR msg through the log.
#define IOMMU_MMIO_STATUS_0_PPR_OVERFLOW_EARLY_OFFSET      18
#define IOMMU_MMIO_STATUS_0_PPR_OVERFLOW_EARLY_MASK        0x40000

// Bitfield Description : Reserved for future use. This register controls no hardware
#define IOMMU_MMIO_STATUS_0_Reserved_31_19_OFFSET      19
#define IOMMU_MMIO_STATUS_0_Reserved_31_19_MASK        0xfff80000

typedef union {
  struct {
    UINT32                            EVENT_OVERFLOW:1;
    UINT32                            EVENT_LOGINT:1;
    UINT32                            COMWAIT_INT:1;
    UINT32                            EVENT_LOGRUN:1;
    UINT32                            CMD_BUFRUN:1;
    UINT32                            PPR_OVERFLOW:1;
    UINT32                            PPR_INT:1;
    UINT32                            PPR_RUN:1;
    UINT32                            GA_RUN:1;
    UINT32                            GA_OVERFLOW:1;
    UINT32                            GA_INT:1;
    UINT32                            PPR_B_OVERFLOW:1;
    UINT32                            PPR_BUF_ACTIVE:1;
    UINT32                            Reserved_14_13:2;
    UINT32                            EVENT_B_OVERFLOW:1;
    UINT32                            EVENT_BUF_ACTIVE:1;
    UINT32                            PPR_B_OVERFLOW_EARLY:1;
    UINT32                            PPR_OVERFLOW_EARLY:1;
    UINT32                            Reserved_31_19:13;
  } Field;
  UINT32 Value;
} IOMMU_MMIO_STATUS_0_STRUCT;

